const test = require('node:test');
const assert = require('node:assert/strict');

const { isScheduled } = require('../src/domain/schedule');
const { calculateCurrentStreak, calculateBestStreak } = require('../src/domain/streak');

const asDate = (value) => new Date(value + 'T12:00:00Z');

test('daily schedule is true for every date', () => {
  const habit = { schedule_type: 'daily', start_date: '2026-09-01' };
  assert.equal(isScheduled(habit, asDate('2026-09-03')), true);
});

test('weekday schedule ignores weekends', () => {
  const habit = { schedule_type: 'weekdays', start_date: '2026-09-01' };
  assert.equal(isScheduled(habit, asDate('2026-09-05')), true); // Saturday
  assert.equal(isScheduled(habit, asDate('2026-09-06')), false); // Sunday
  assert.equal(isScheduled(habit, asDate('2026-09-07')), true); // Monday
});

test('custom weekday schedule respects selected weekdays', () => {
  const habit = { schedule_type: 'custom_weekdays', custom_weekdays: '1,3,5', start_date: '2026-09-01' };
  assert.equal(isScheduled(habit, asDate('2026-09-02')), true); // Wednesday = 3
  assert.equal(isScheduled(habit, asDate('2026-09-04')), false); // Friday? Actually 2026-09-04 is Friday => 5, so should be true
  assert.equal(isScheduled(habit, asDate('2026-09-03')), false); // Thursday = 4
});

test('current streak preserves previous run when today is scheduled but incomplete', () => {
  const habit = { id: 1, schedule_type: 'daily', start_date: '2026-09-01' };
  const completed = ['2026-09-01', '2026-09-02', '2026-09-03'];
  const current = calculateCurrentStreak(habit, completed, '2026-09-04');
  assert.equal(current, 3);
});

test('missed scheduled occurrence breaks the streak', () => {
  const habit = { id: 1, schedule_type: 'daily', start_date: '2026-09-01' };
  const completed = ['2026-09-01', '2026-09-03'];
  const current = calculateCurrentStreak(habit, completed, '2026-09-03');
  assert.equal(current, 1);
});

test('best streak is the longest completed run', () => {
  const habit = { id: 1, schedule_type: 'daily', start_date: '2026-09-01' };
  const completed = ['2026-09-01', '2026-09-02', '2026-09-04', '2026-09-05', '2026-09-06'];
  const best = calculateBestStreak(habit, completed, '2026-09-06');
  assert.equal(best, 3);
});

const sqlite3 = require('sqlite3').verbose();
const path = require('path');

const dbPath = path.join(__dirname, '..', 'db', 'habit-tracker.sqlite');

const db = new sqlite3.Database(dbPath, (err) => {
  if (err) {
    console.error('Failed to connect to SQLite database:', err.message);
  } else {
    console.log('Connected to SQLite database');
  }
});

module.exports = db;

function toISODate(date) {
  const d = new Date(date);
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function addDays(dateString, amount) {
  const date = new Date(dateString + 'T12:00:00Z');
  date.setUTCDate(date.getUTCDate() + amount);
  return toISODate(date);
}

function parseISODate(dateString) {
  return new Date(dateString + 'T12:00:00Z');
}

function dayOfWeek(dateString) {
  return parseISODate(dateString).getUTCDay();
}

function isSameDate(a, b) {
  return toISODate(a) === toISODate(b);
}

module.exports = {
  toISODate,
  addDays,
  parseISODate,
  dayOfWeek,
  isSameDate,
};

const { dayOfWeek } = require('./dateUtils');

function parseCustomWeekdays(raw) {
  if (!raw) return new Set();
  return new Set(
    String(raw)
      .split(',')
      .map((value) => Number(value.trim()))
      .filter((value) => Number.isInteger(value) && value >= 0 && value <= 6)
  );
}

function isScheduled(habit, date) {
  if (!habit || !date) return false;

  const dateString = date instanceof Date ? date.toISOString().slice(0, 10) : String(date);
  const weekday = dayOfWeek(dateString);

  if (habit.start_date && dateString < habit.start_date) return false;

  switch (habit.schedule_type) {
    case 'daily':
      return true;
    case 'weekdays':
      return weekday >= 1 && weekday <= 5;
    case 'custom_weekdays': {
      const custom = parseCustomWeekdays(habit.custom_weekdays);
      return custom.has(weekday);
    }
    default:
      return false;
  }
}

module.exports = {
  isScheduled,
  parseCustomWeekdays,
};

const { addDays, parseISODate } = require('./dateUtils');
const { isScheduled } = require('./schedule');

function getScheduledDates(habit, startDate, endDate) {
  const dates = [];
  let current = startDate;
  while (current <= endDate) {
    if (isScheduled(habit, current)) {
      dates.push(current);
    }
    current = addDays(current, 1);
  }
  return dates;
}

function calculateBestStreak(habit, completedDates, asOfDate = null) {
  const completedSet = new Set(completedDates || []);
  const endDate = asOfDate || completedDates[completedDates.length - 1] || habit.start_date;

  if (!habit.start_date) {
    return 0;
  }

  const scheduledDates = getScheduledDates(habit, habit.start_date, endDate);
  if (!scheduledDates.length) return 0;

  let best = 0;
  let current = 0;

  for (const date of scheduledDates) {
    if (completedSet.has(date)) {
      current += 1;
      best = Math.max(best, current);
    } else {
      current = 0;
    }
  }

  return best;
}

function calculateCurrentStreak(habit, completedDates, asOfDate) {
  const completedSet = new Set(completedDates || []);
  const endDate = asOfDate || new Date().toISOString().slice(0, 10);
  const startDate = habit.start_date || endDate;

  const scheduledDates = getScheduledDates(habit, startDate, endDate);
  if (!scheduledDates.length) return 0;

  let current = 0;
  let foundLastCompleted = false;

  for (let i = scheduledDates.length - 1; i >= 0; i -= 1) {
    const date = scheduledDates[i];

    if (completedSet.has(date)) {
      current += 1;
      foundLastCompleted = true;
      continue;
    }

    if (foundLastCompleted) {
      return current;
    }

    // ignore missed dates before the first completed occurrence
    if (!foundLastCompleted) {
      continue;
    }
  }

  if (foundLastCompleted) return current;
  return 0;
}

module.exports = {
  getScheduledDates,
  calculateBestStreak,
  calculateCurrentStreak,
};

const db = require('../../config/db');

function listHabits() {
  return new Promise((resolve, reject) => {
    db.all(
      `SELECT * FROM habits ORDER BY is_archived ASC, created_at DESC`,
      [],
      (err, rows) => {
        if (err) reject(err);
        else resolve(rows);
      }
    );
  });
}

function getHabitById(id) {
  return new Promise((resolve, reject) => {
    db.get('SELECT * FROM habits WHERE id = ?', [id], (err, row) => {
      if (err) reject(err);
      else resolve(row || null);
    });
  });
}

function createHabit(habitData) {
  return new Promise((resolve, reject) => {
    const {
      user_id,
      name,
      schedule_type,
      custom_weekdays,
      is_archived,
      start_date,
      created_at,
      updated_at,
    } = habitData;

    db.run(
      `INSERT INTO habits (user_id, name, schedule_type, custom_weekdays, is_archived, start_date, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      [user_id, name, schedule_type, custom_weekdays || null, is_archived ? 1 : 0, start_date, created_at, updated_at],
      function (err) {
        if (err) return reject(err);
        resolve(this.lastID);
      }
    );
  });
}

function updateHabit(id, updates) {
  return new Promise((resolve, reject) => {
    const fields = [];
    const values = [];

    Object.entries(updates).forEach(([key, value]) => {
      if (value !== undefined) {
        fields.push(`${key} = ?`);
        values.push(value);
      }
    });

    if (!fields.length) return resolve(0);

    values.push(id);

    db.run(
      `UPDATE habits SET ${fields.join(', ')} WHERE id = ?`,
      values,
      function (err) {
        if (err) return reject(err);
        resolve(this.changes);
      }
    );
  });
}

function archiveHabit(id) {
  return updateHabit(id, { is_archived: 1, updated_at: new Date().toISOString() });
}

function restoreHabit(id) {
  return updateHabit(id, { is_archived: 0, updated_at: new Date().toISOString() });
}

function searchHabits(query) {
  return new Promise((resolve, reject) => {
    const normalized = `%${query}%`;
    db.all(
      `SELECT * FROM habits WHERE name LIKE ? ORDER BY is_archived ASC, created_at DESC`,
      [normalized],
      (err, rows) => {
        if (err) reject(err);
        else resolve(rows);
      }
    );
  });
}

module.exports = {
  listHabits,
  getHabitById,
  createHabit,
  updateHabit,
  archiveHabit,
  restoreHabit,
  searchHabits,
};

const db = require('../../config/db');

function getCompletedDates(habitId) {
  return new Promise((resolve, reject) => {
    db.all(
      `SELECT date_key FROM habit_completions WHERE habit_id = ? ORDER BY date_key ASC`,
      [habitId],
      (err, rows) => {
        if (err) reject(err);
        else resolve(rows.map((row) => row.date_key));
      }
    );
  });
}

function completeHabitForDate(habitId, dateKey) {
  return new Promise((resolve, reject) => {
    db.run(
      `INSERT INTO habit_completions (habit_id, date_key, completed_at)
       VALUES (?, ?, ?)`,
      [habitId, dateKey, new Date().toISOString()],
      function (err) {
        if (err) return reject(err);
        resolve({ id: this.lastID, habitId, dateKey });
      }
    );
  });
}

function uncompleteHabitForDate(habitId, dateKey) {
  return new Promise((resolve, reject) => {
    db.run(
      `DELETE FROM habit_completions WHERE habit_id = ? AND date_key = ?`,
      [habitId, dateKey],
      function (err) {
        if (err) return reject(err);
        resolve(this.changes);
      }
    );
  });
}

module.exports = {
  getCompletedDates,
  completeHabitForDate,
  uncompleteHabitForDate,
};

const { toISODate } = require('../domain/dateUtils');
const { isScheduled } = require('../domain/schedule');
const { calculateCurrentStreak, calculateBestStreak, getScheduledDates } = require('../domain/streak');
const habitRepository = require('../repositories/habitRepository');
const completionRepository = require('../repositories/completionRepository');

async function listHabits() {
  return habitRepository.listHabits();
}

async function getHabitById(id) {
  return habitRepository.getHabitById(id);
}

async function createHabit(payload) {
  const name = String(payload.name || '').trim();
  const scheduleType = payload.schedule_type;

  if (!name) {
    const err = new Error('Habit name is required.');
    err.statusCode = 400;
    throw err;
  }

  if (!['daily', 'weekdays', 'custom_weekdays'].includes(scheduleType)) {
    const err = new Error('Invalid schedule type.');
    err.statusCode = 400;
    throw err;
  }

  if (scheduleType === 'custom_weekdays') {
    const selected = String(payload.custom_weekdays || '').split(',').map((value) => value.trim());
    const valid = selected.filter((value) => value !== '');
    if (!valid.length) {
      const err = new Error('Custom schedule requires at least one selected weekday.');
      err.statusCode = 400;
      throw err;
    }
  }

  const now = new Date().toISOString();
  const startDate = payload.start_date || toISODate(new Date());

  const id = await habitRepository.createHabit({
    user_id: 1,
    name,
    schedule_type: scheduleType,
    custom_weekdays: payload.custom_weekdays || null,
    is_archived: Boolean(payload.is_archived),
    start_date: startDate,
    created_at: now,
    updated_at: now,
  });

  return id;
}

async function updateHabit(id, payload) {
  const habit = await habitRepository.getHabitById(id);
  if (!habit) {
    const err = new Error('Habit not found.');
    err.statusCode = 404;
    throw err;
  }

  const updates = {};

  if (payload.name !== undefined) {
    const name = String(payload.name).trim();
    if (!name) {
      const err = new Error('Habit name is required.');
      err.statusCode = 400;
      throw err;
    }
    updates.name = name;
  }

  if (payload.schedule_type !== undefined) {
    if (!['daily', 'weekdays', 'custom_weekdays'].includes(payload.schedule_type)) {
      const err = new Error('Invalid schedule type.');
      err.statusCode = 400;
      throw err;
    }
    updates.schedule_type = payload.schedule_type;
  }

  if (payload.custom_weekdays !== undefined) {
    updates.custom_weekdays = payload.custom_weekdays || null;
  }

  if (payload.start_date !== undefined) {
    updates.start_date = payload.start_date;
  }

  updates.updated_at = new Date().toISOString();

  return habitRepository.updateHabit(id, updates);
}

async function archiveHabit(id) {
  const habit = await habitRepository.getHabitById(id);
  if (!habit) {
    const err = new Error('Habit not found.');
    err.statusCode = 404;
    throw err;
  }

  return habitRepository.archiveHabit(id);
}

async function restoreHabit(id) {
  const habit = await habitRepository.getHabitById(id);
  if (!habit) {
    const err = new Error('Habit not found.');
    err.statusCode = 404;
    throw err;
  }

  return habitRepository.restoreHabit(id);
}

async function searchHabits(query) {
  const q = String(query || '').trim();
  if (!q) return listHabits();
  return habitRepository.searchHabits(q);
}

async function getTodayDashboard() {
  const habits = await listHabits();
  const today = toISODate(new Date());

  const items = [];

  for (const habit of habits) {
    if (habit.is_archived) continue;
    if (!isScheduled(habit, today)) continue;

    const completedDates = await completionRepository.getCompletedDates(habit.id);
    const currentStreak = calculateCurrentStreak(habit, completedDates, today);
    const bestStreak = calculateBestStreak(habit, completedDates, today);
    const isComplete = completedDates.includes(today);

    items.push({
      ...habit,
      current_streak: currentStreak,
      best_streak: bestStreak,
      is_complete: isComplete,
    });
  }

  return items;
}

async function getHabitWithStats(habitId) {
  const habit = await habitRepository.getHabitById(habitId);
  if (!habit) {
    const err = new Error('Habit not found.');
    err.statusCode = 404;
    throw err;
  }

  const completedDates = await completionRepository.getCompletedDates(habitId);
  const today = toISODate(new Date());

  return {
    ...habit,
    current_streak: calculateCurrentStreak(habit, completedDates, today),
    best_streak: calculateBestStreak(habit, completedDates, today),
    is_complete: completedDates.includes(today),
    completed_dates: completedDates,
  };
}

async function getAllHabitsWithStats() {
  const habits = await listHabits();
  const today = toISODate(new Date());

  const mapped = [];
  for (const habit of habits) {
    const completedDates = await completionRepository.getCompletedDates(habit.id);
    mapped.push({
      ...habit,
      current_streak: calculateCurrentStreak(habit, completedDates, today),
      best_streak: calculateBestStreak(habit, completedDates, today),
      is_complete: completedDates.includes(today),
    });
  }

  return mapped;
}

module.exports = {
  listHabits,
  getHabitById,
  createHabit,
  updateHabit,
  archiveHabit,
  restoreHabit,
  searchHabits,
  getTodayDashboard,
  getHabitWithStats,
  getAllHabitsWithStats,
};

const { toISODate } = require('../domain/dateUtils');
const completionRepository = require('../repositories/completionRepository');
const habitRepository = require('../repositories/habitRepository');

async function completeHabit(habitId) {
  const habit = await habitRepository.getHabitById(habitId);
  if (!habit) {
    const err = new Error('Habit not found.');
    err.statusCode = 404;
    throw err;
  }

  const today = toISODate(new Date());
  const existing = await completionRepository.getCompletedDates(habitId);

  if (existing.includes(today)) {
    return { alreadyCompleted: true, dateKey: today };
  }

  const result = await completionRepository.completeHabitForDate(habitId, today);
  return { alreadyCompleted: false, ...result };
}

async function uncompleteHabit(habitId) {
  const habit = await habitRepository.getHabitById(habitId);
  if (!habit) {
    const err = new Error('Habit not found.');
    err.statusCode = 404;
    throw err;
  }

  const today = toISODate(new Date());
  const deleted = await completionRepository.uncompleteHabitForDate(habitId, today);
  return { deletedCount: deleted };
}

module.exports = {
  completeHabit,
  uncompleteHabit,
};

const habitService = require('../services/habitService');

async function renderDashboard(req, res) {
  try {
    const habits = await habitService.getTodayDashboard();
    const allHabits = await habitService.getAllHabitsWithStats();

    res.render('dashboard', {
      title: 'Habit Dashboard',
      habits,
      allHabits,
      error: null,
      success: null,
    });
  } catch (error) {
    console.error(error);
    res.status(500).render('dashboard', {
      title: 'Habit Dashboard',
      habits: [],
      allHabits: [],
      error: 'Unable to load the dashboard right now.',
      success: null,
    });
  }
}

module.exports = {
  renderDashboard,
};

const habitService = require('../services/habitService');
const completionService = require('../services/completionService');

async function renderHabitList(req, res) {
  try {
    const query = req.query.q || '';
    const habits = await habitService.searchHabits(query);

    res.render('habits', {
      title: 'Habits',
      habits,
      query,
      error: null,
      success: null,
    });
  } catch (error) {
    console.error(error);
    res.status(500).render('habits', {
      title: 'Habits',
      habits: [],
      query: '',
      error: 'Unable to load habits.',
      success: null,
    });
  }
}

async function renderNewHabitForm(req, res) {
  res.render('habitEdit', {
    title: 'New Habit',
    habit: null,
    mode: 'new',
    error: null,
    success: null,
  });
}

async function createHabit(req, res) {
  try {
    const habitId = await habitService.createHabit(req.body);
    res.redirect('/habits');
  } catch (error) {
    console.error(error);
    res.status(error.statusCode || 500).render('habitEdit', {
      title: 'New Habit',
      habit: { ...req.body },
      mode: 'new',
      error: error.message || 'Unable to create habit.',
      success: null,
    });
  }
}

async function renderEditHabitForm(req, res) {
  try {
    const habit = await habitService.getHabitById(req.params.id);
    if (!habit) {
      return res.status(404).render('habitEdit', {
        title: 'Edit Habit',
        habit: null,
        mode: 'edit',
        error: 'Habit not found.',
        success: null,
      });
    }

    res.render('habitEdit', {
      title: 'Edit Habit',
      habit,
      mode: 'edit',
      error: null,
      success: null,
    });
  } catch (error) {
    console.error(error);
    res.status(500).render('habitEdit', {
      title: 'Edit Habit',
      habit: null,
      mode: 'edit',
      error: 'Unable to load habit.',
      success: null,
    });
  }
}

async function updateHabit(req, res) {
  try {
    await habitService.updateHabit(req.params.id, req.body);
    res.redirect('/habits');
  } catch (error) {
    console.error(error);
    const habit = await habitService.getHabitById(req.params.id);
    res.status(error.statusCode || 500).render('habitEdit', {
      title: 'Edit Habit',
      habit: habit || { ...req.body },
      mode: 'edit',
      error: error.message || 'Unable to update habit.',
      success: null,
    });
  }
}

async function archiveHabit(req, res) {
  try {
    await habitService.archiveHabit(req.params.id);
    res.redirect('/habits');
  } catch (error) {
    console.error(error);
    res.status(error.statusCode || 500).send(error.message || 'Unable to archive habit.');
  }
}

async function restoreHabit(req, res) {
  try {
    await habitService.restoreHabit(req.params.id);
    res.redirect('/habits');
  } catch (error) {
    console.error(error);
    res.status(error.statusCode || 500).send(error.message || 'Unable to restore habit.');
  }
}

async function completeHabit(req, res) {
  try {
    await completionService.completeHabit(req.params.id);
    res.redirect('/');
  } catch (error) {
    console.error(error);
    res.status(error.statusCode || 500).send(error.message || 'Unable to complete habit.');
  }
}

async function uncompleteHabit(req, res) {
  try {
    await completionService.uncompleteHabit(req.params.id);
    res.redirect('/');
  } catch (error) {
    console.error(error);
    res.status(error.statusCode || 500).send(error.message || 'Unable to uncomplete habit.');
  }
}

module.exports = {
  renderHabitList,
  renderNewHabitForm,
  createHabit,
  renderEditHabitForm,
  updateHabit,
  archiveHabit,
  restoreHabit,
  completeHabit,
  uncompleteHabit,
};

