test('today scheduled and incomplete habit appears in reminders', async () => {
  const today = '2026-09-16';
  const habits = [{
    id: 1,
    user_id: 1,
    name: 'Drink Water',
    schedule_type: 'daily',
    is_archived: 0,
    start_date: '2026-09-01',
  }];

  const original = await habitService.listHabits();
  const originalCompleted = await Promise.all(original.map(async (habit) => ({
    id: habit.id,
    dates: await require('../src/repositories/completionRepository').getCompletedDates(habit.id),
  })));

  const incompleteHabits = await habitService.getPendingTodayHabits(1, today);
  assert.ok(incompleteHabits.some((habit) => habit.name === 'Drink Water'));

  await Promise.all(originalCompleted.map(async ({ id, dates }) => {
    if (dates.includes(today)) {
      await require('../src/repositories/completionRepository').uncompleteHabitForDate(id, today);
    }
  }));
});

